       36: /*                                                                      */
       37: /*      Create an overview cache to hold two rows of blocks from an     */
       38: /*      existing TIFF directory.                                        */
       39: /************************************************************************/
       40: 
       41: TIFFOvrCache *TIFFCreateOvrCache(TIFF *hTIFF, toff_t nDirOffset)
       42: 
       43: {
       44:     TIFFOvrCache *psCache;
       45:     toff_t nBaseDirOffset;
       46:     int nRet;
       47: 
       48:     psCache = (TIFFOvrCache *)_TIFFmalloc(sizeof(TIFFOvrCache));
>>>    49:     psCache->nDirOffset = nDirOffset;
       50:     psCache->hTIFF = hTIFF;
       51: 
       52:     /* -------------------------------------------------------------------- */
       53:     /*      Get definition of this raster from the TIFF file itself.        */
       54:     /* -------------------------------------------------------------------- */
       55:     nBaseDirOffset = TIFFCurrentDirOffset(psCache->hTIFF);
       56:     nRet = TIFFSetSubDirectory(hTIFF, nDirOffset);
       57:     (void)nRet;
       58:     assert(nRet == 1);
       59: 
       60:     TIFFGetField(hTIFF, TIFFTAG_IMAGEWIDTH, &(psCache->nXSize));
       61:     TIFFGetField(hTIFF, TIFFTAG_IMAGELENGTH, &(psCache->nYSize));
       62: 
       63:     TIFFGetField(hTIFF, TIFFTAG_BITSPERSAMPLE, &(psCache->nBitsPerPixel));
       64:     TIFFGetField(hTIFF, TIFFTAG_SAMPLESPERPIXEL, &(psCache->nSamples));
       65:     TIFFGetField(hTIFF, TIFFTAG_PLANARCONFIG, &(psCache->nPlanarConfig));
       66: 
       67:     if (!TIFFIsTiled(hTIFF))
       68:     {
       69:         TIFFGetField(hTIFF, TIFFTAG_ROWSPERSTRIP, &(psCache->nBlockYSize));
       70:         psCache->nBlockXSize = psCache->nXSize;
       71:         psCache->nBytesPerBlock = TIFFStripSize(hTIFF);
       72:         psCache->bTiled = FALSE;
       73:     }
       74:     else
       75:     {
       76:         TIFFGetField(hTIFF, TIFFTAG_TILEWIDTH, &(psCache->nBlockXSize));
       77:         TIFFGetField(hTIFF, TIFFTAG_TILELENGTH, &(psCache->nBlockYSize));
       78:         psCache->nBytesPerBlock = TIFFTileSize(hTIFF);
       79:         psCache->bTiled = TRUE;
       80:     }
